template<typename T>

class Matrix {

public:

  vector<vector<T>> A;

  int H, W;



  Matrix(int h, int w, T val = T()) : H(h), W(w) {

    A.assign(H, vector<T>(W, val));

  }



  void fill(T val) {

    rep(i, H) rep(j, W) A[i][j] = val;

  }



  static Matrix I(int n) {

    Matrix res(n, n);

    rep(i, n) res.A[i][i] = 1;

    return res;

  }



  friend ostream& operator<<(ostream &os, const Matrix &m) {

    rep(i, m.H) {

      rep(j, m.W) os << m.A[i][j] << " ";

      os << "\n";

    }

    return os;

  }



  Matrix operator*(const Matrix &B) const {

    assert(W == B.H);

    int N = W;

    Matrix<C> C(H, B.W);

    rep(i, H) rep(j, B.W) rep(k, N) C.A[i][j] += A[i][k] * B.A[k][j];

    return C;

  }



  Matrix pow(ll k) const {

    assert(H == W);

    Matrix<C> res = Matrix<C>::I(H);

    Matrix<C> A = *this;

    while(k > 0) {

      if(k & 1) res = res * A;

      A = A * A;

      k >>= 1;

    }

    return res;

  }

};



template<typename T>

class SegTree {

public:

  int n;

  vector<T> dat;



  SegTree() : n(0) {}



  SegTree(int n_, T e) : n(n_) {

    dat.assign(n * 2, e);

  }



  void build() {

    for(int i = n - 1; i > 0; i--) dat[i] = dat[i * 2] + dat[i * 2 + 1];

  }



  void update(int k, T x) {

    k += n;

    dat[k] = x;

    while(k > 0) {

      k /= 2;

      dat[k] = dat[k * 2] + dat[k * 2 + 1];

    }

  }



  T query(int l, int r) {

    L = l; R = r;

    return query(1, 0, n);

  }



private:

  int L, R;



  T query(int k, int l, int r) {

    if(r <= L || R <= l) return T();

    if(L <= l && r <= R) return dat[k];

    return query(k * 2, l, (l + r) / 2) + query(k * 2 + 1, (l + r) / 2, r);

  }

};



