template<typename T>

class BIT {

public:

  int n;

  vector<T> dat;



  BIT() : n(0) {}



  BIT(int n_) : n(n_) {

    dat.assign(n + 1, T());

  }



  void add(int k, T x) {

    for(++k; k <= n; k += k & -k) dat[k] += x;

  }



  T sum(int k) {

    T res = T();

    for(++k; k > 0; k -= k & -k) res += dat[k];

    return res;

  }



  T sum(int l, int r) {

    return sum(r) - sum(l - 1);

  }

};



template<typename T>

class UnionFind {

public:

  vector<int> par, rank;



  UnionFind() {}



  UnionFind(int n) {

    par.assign(n, -1);

    rank.assign(n, 0);

  }



  int find(int x) {

    if(par[x] < 0) return x;

    else return par[x] = find(par[x]);

  }



  bool same(int x, int y) {

    return find(x) == find(y);

  }



  void unite(int x, int y) {

    x = find(x);

    y = find(y);

    if(x == y) return;

    if(rank[x] < rank[y]) swap(x, y);

    par[x] += par[y];

    par[y] = x;

  }



  int size(int x) {

    return -par[find(x)];

  }

};



template<typename T>

class RangeUpdateRangeQuery {

public:

  int n;

  vector<T> dat;



  RangeUpdateRangeQuery() : n(0) {}



  RangeUpdateRangeQuery(int n_) : n(n_) {

    dat.assign(n * 2, T());

  }



  void update(int l, int r, T x) {

    l += n; r += n;

    while(l < r) {

      if(l & 1) dat[l++] = x;

      if(r & 1) dat[--r] = x;

      l >>= 1; r >>= 1;

    }

  }



  T query(int k) {

    k += n;

    T res = dat[k];

    while(k > 0) {

      k >>= 1;

      res += dat[k];

    }

    return res;

  }

};



