template<typename T>

class Matrix {

public:

  vector<vector<T>> A;

  int H, W;



  Matrix(int h, int w, T val = T()) : H(h), W(w) {

    A.assign(H, vector<T>(W, val));

  }



  void fill(T val) {

    rep(i, H) rep(j, W) A[i][j] = val;

  }



  static Matrix I(int n) {

    Matrix res(n, n);

    rep(i, n) res.A[i][i] = 1;

    return res;

  }



  friend ostream& operator<<(ostream &os, const Matrix &m) {

    rep(i, m.H) {

      rep(j, m.W) os << m.A[i][j] << " ";

      os << "\n";

    }

    return os;

  }



  Matrix operator*(const Matrix &B) const {

    assert(W == B.H);

    int N = H, M = W, L = B.W;

    Matrix C(N, L);

    rep(i, N) rep(j, L) rep(k, M) C.A[i][j] += A[i][k] * B.A[k][j];

    return C;

  }



  Matrix pow(ll k) const {

    assert(H == W);

    Matrix B = *this;

    Matrix res = I(H);

    while(k > 0) {

      if(k & 1) res = res * B;

      B = B * B;

      k >>= 1;

    }

    return res;

  }

};



