      dat[i] = op(dat[i * 2], dat[i * 2 + 1]);

    }

  }



  T query(int l, int r) {

    l += n;

    r += n;

    T L = e(), R = e();

    while(l < r) {

      if(l & 1) L = op(L, dat[l++]);

      if(r & 1) R = op(dat[--r], R);

      l /= 2;

      r /= 2;

    }

    return op(L, R);

  }



  T operator[](int i) {

    return dat[i + n];

  }



private:

  T op(T x, T y) {

    return min(x, y);

  }



  T e() {

    return INF;

  }

};



