inline int adler32(char* buf, int len) {
	int s1 = 1, s2 = 0;
	for (int i = 0; i < len; i++) {
		s1 = (s1 + buf[i]) % MOD;
		s2 = (s2 + s1) % MOD;
	}
	return (s2 << 16) | s1;
}

int main() {
	scanf("%d%d%llu", &n, &k, &seed);
	sprintf(buf, "%llu", seed);
	for (int i = 0; i < n; i++) buf[i] = 'a' + (buf[i] - '0') % 26;
	int ans = 1;
	for (int i = 0; i < k; i++) ans = adler32(buf, n > 64 ? n - (i % 61) : n);
	printf("%d\n", ans);
	return 0;
}

