#include <cstdio>
#include <cstring>

#define MAXN 100000

unsigned long long seed;

unsigned long long rnd() {
	seed ^= seed << 13;
	seed ^= seed >> 7;
	seed ^= seed << 17;
	return seed;
}

int main() {
	int n, k;
	unsigned long long ans = 0;
	scanf("%d%d%llu", &n, &k, &seed);
	for (int i = 0; i < k; i++) {
		char buf[MAXN * 10];
		int len = 0;
		for (int j = 0; j < n; j++) {
			unsigned long long x = rnd() >> (rnd() % 64);
			if (j & 1) {
				buf[len++] = x & 0x7f;
				x >>= 7;
				while (x) {
					buf[len++] = (x & 0x7f) | 0x80;
					x >>= 7;
				}
			} else {
				buf[len++] = x & 0xff;
				x >>= 8;
				while (x) {
					buf[len++] = (x & 0xff) | 0x80;
					x >>= 8;
				}
			}
		}
		ans ^= len;
		const char *p = buf;
		for (int j = 0; j < n; j++) {
			if (j & 1) {
				unsigned long long x = 0;
				do {
					x = (x << 7) | (*p & 0x7f);
				} while (*p++ & 0x80);
				ans = ans * 31 + x;
			} else {
				unsigned long long x = 0;
				do {
					x = (x << 8) | (*p & 0xff);
				} while (*p++ & 0x80);
				ans = ans * 31 + x;
			}
		}
	}
	printf("%llu\n", ans);
	return 0;
}

