template<typename F>

struct rollback_union_find {

  vector<int> par;

  vector<int> rank;

  vector<int> size;

  vector<F> history;

  rollback_union_find(int n) : par(n, -1), rank(n, 0), size(n, 1) {}

  int find(int x){

    if(par[x] == -1) return x;

    else return par[x] = find(par[x]);

  }

  void unite(int x, int y, F f){

    x = find(x);

    y = find(y);

    if(x == y) return;

    if(rank[x] < rank[y]) swap(x, y);

    history.pb(f);

    if(rank[x] == rank[y]) rank[x]++;

    par[y] = x;

    size[x] += size[y];

  }

  int get_size(int x){

    return size[find(x)];

  }

  void rollback(){

    int x = history.back();

    history.pop_back();

    par[x] = -1;

    rank[x] = 0;

    size[x] = 1;

  }

};

