template<typename T>

struct Matrix {

    vector<vector<T>> A;

    int H, W;



    Matrix(int h, int w, T e = T()) : H(h), W(w), A(h, vector<T>(w, e)) {}

    Matrix(int h, int w, vector<T> v) : H(h), W(w), A(h, vector<T>(w)) {

        rep(i, h) rep(j, w) A[i][j] = v[i*w+j];

    }



    inline const vector<T>& operator [] (int i) const { return A.at(i); }

    inline vector<T>& operator [] (int i) { return A.at(i); }



    static Matrix I(int n) {

        Matrix<mint> mat(n, n);

        rep(i, n) mat[i][i] = 1;

        return mat;

    }



    Matrix<T> operator + (const Matrix<T> &B) const {

        assert(H == B.H && W == B.W);

        Matrix<T> C(H, W);

        rep(i, H) rep(j, W) C[i][j] = A[i][j] + B[i][j];

        return C;

    }



    Matrix<T> operator - (const Matrix<T> &B) const {

        assert(H == B.H && W == B.W);

        Matrix<T> C(H, W);

        rep(i, H) rep(j, W) C[i][j] = A[i][j] - B[i][j];

        return C;

    }



    Matrix<T> operator * (const Matrix<T> &B) const {

        assert(W == B.H);

        Matrix<T> C(H, B.W);

        rep(i, H) rep(j, B.W) rep(k, W) C[i][j] += A[i][k] * B[k][j];

        return C;

    }



    Matrix<T> pow(long long k) const {

        assert(H == W);

        Matrix<T> M = Matrix<T>::I(H);

        Matrix<T> A = *this;

        while(k > 0) {

            if(k & 1) M = M * A;

            A = A * A;

            k >>= 1;

        }

        return M;

    }



    void print() {

        rep(i, H) {

            rep(j, W) cout << A[i][j] << " ";

            cout << endl;

        }

    }

};



struct mint {

    ll val;

    constexpr mint(ll v = 0): val(v % MOD) { if(val < 0) val += MOD; }

    constexpr mint& operator += (mint other) { val += other.val; if(val >= MOD) val -= MOD; return *this; }

    constexpr mint& operator -= (mint other) { val -= other.val; if(val < 0) val += MOD; return *this; }

    constexpr mint& operator *= (mint other) { val = val * other.val % MOD; return *this; }

    constexpr mint& operator /= (mint other) { return *this *= other.inv(); }

    constexpr mint operator + (mint other) const { return mint(*this) += other; }

    constexpr mint operator - (mint other) const { return mint(*this) -= other; }

    constexpr mint operator * (mint other) const { return mint(*this) *= other; }

    constexpr mint operator / (mint other) const { return mint(*this) /= other; }

    constexpr mint inv() const { return pow(MOD-2); }

    constexpr mint pow(ll t) const {

        @footnote{https://blog.narutouzuki.com/entry/2019/05/09/235814}

        if(t == 0) return 1;

        mint a = pow(t>>1);

        a *= a;

        if(t&1) a *= *this;

        return a;

    }

    constexpr bool operator == (mint other) const { return val == other.val; }

    constexpr bool operator != (mint other) const { return val != other.val; }

    constexpr bool operator < (mint other) const { return val < other.val; }

    constexpr bool operator > (mint other) const { return val > other.val; }

    constexpr bool operator <= (mint other) const { return val <= other.val; }

    constexpr bool operator >= (mint other) const { return val >= other.val; }

    constexpr mint operator + () const { return *this; }

    constexpr mint operator - () const { return mint()-*this; }

    mint& operator ++ () { return (*this) += 1; }

    mint& operator -- () { return (*this) -= 1; }

    mint operator ++ (int) { mint tmp = *this; (*this) += 1; return tmp; }

    mint operator -- (int) { mint tmp = *this; (*this) -= 1; return tmp; }

    friend ostream& operator << (ostream &os, const mint &m) { return os << m.val; }

    friend istream& operator >> (istream &is, mint &m) { ll z; is >> z; m = z; return is; }

};



int main() {

    cin.tie(0);

    ios::sync_with_stdio(false);



    int m, len, maxd;

    unsigned long long seed;

    cin >> m >> len >> maxd >> seed;



    srand(seed);

    vector<string> S(m);

    rep(i, m) {

        string s;

        rep(j, len) s.pb('a' + rand()%8);

        S[i] = s;

    }



    vector<vector<int>> dp(m, vector<int>(m));

    rep(i, m) rep(j, m) {

        if(i == j) continue;

        int d = 0;

        rep(k, len) {

            if(S[i][k] != S[j][k]) d++;

            if(d > maxd) break;

        }

        dp[i][j] = d;

    }



    matrix<mint> M(m, m);

    rep(i, m) rep(j, m) M[i][j] = dp[i][j];



    mint ans = 0;

    rep(i, m) rep(j, m) {

        if(i == j) continue;

        ans += M.pow(i)[j];

    }



    cout << ans << endl;

    return 0;

}

