uint32_t hash(uint32_t x) {
  x = (x ^ 61) ^ (x >> 16);
  x = x + (x << 3);
  x = x ^ (x >> 4);
  x = x * 0x27d4eb2d;
  x = x ^ (x >> 15);
  return x;
}

int main() {
  int n, k;
  uint64_t seed;
  scanf("%d%d%lu", &n, &k, &seed);
  uint32_t x = seed;
  uint32_t ans = 0;
  for (int i = 0; i < k; i++) {
    x = hash(x);
    ans = ans * 31 + (x % n + 1);
  }
  printf("%u\n", ans);
  return 0;
}

