typedef unsigned long long ull;

ull rnd(ull &st) {
	st ^= st << 13;
	st ^= st >> 7;
	st ^= st << 17;
	return st;
}

ull siphash(const char *in, int len, const char *key) {
	ull v0 = 0x736f6d6570736575ULL;
	ull v1 = 0x646f72616e646f6dULL;
	ull v2 = 0x6c7967656e657261ULL;
	ull v3 = 0x7465646279746573ULL;
	ull k0 = *(ull *)key;
	ull k1 = *(ull *)(key + 8);
	ull m;
	const char *end = in + len - (len % 8);
	const int left = len & 7;
	ull b = ((ull)len) << 56;
	v3 ^= k1;
	v2 ^= k0;
	v1 ^= k1;
	v0 ^= k0;

	for (; in != end; in += 8) {
		m = *(ull *)in;
		v3 ^= m;

		v0 += v1;
		v1 = __builtin_rotateleft64(v1, 13);
		v1 ^= v0;
		v0 = __builtin_rotateleft64(v0, 32);

		v2 += v3;
		v3 = __builtin_rotateleft64(v3, 16);
		v3 ^= v2;
		v2 = __builtin_rotateleft64(v2, 32);

		v0 += v3;
		v3 = __builtin_rotateleft64(v3, 21);
		v3 ^= v0;

		v2 += v1;
		v1 = __builtin_rotateleft64(v1, 17);
		v1 ^= v2;
		v2 = __builtin_rotateleft64(v2, 32);
	}

	switch (left) {
	case 7: b |= ((ull)in[6]) << 48; // fall-through
	case 6: b |= ((ull)in[5]) << 40; // fall-through
	case 5: b |= ((ull)in[4]) << 32; // fall-through
	case 4: b |= ((ull)in[3]) << 24; // fall-through
	case 3: b |= ((ull)in[2]) << 16; // fall-through
	case 2: b |= ((ull)in[1]) << 8; // fall-through
	case 1: b |= ((ull)in[0]); break;
	case 0: break;
	}

	v3 ^= b;

	v0 += v1;
	v1 = __builtin_rotateleft64(v1, 13);
	v1 ^= v0;
	v0 = __builtin_rotateleft64(v0, 32);

	v2 += v3;
	v3 = __builtin_rotateleft64(v3, 16);
	v3 ^= v2;
	v2 = __builtin_rotateleft64(v2, 32);

	v0 += v3;
	v3 = __builtin_rotateleft64(v3, 21);
	v3 ^= v0;

	v2 += v1;
	v1 = __builtin_rotateleft64(v1, 17);
	v1 ^= v2;
	v2 = __builtin_rotateleft64(v2, 32);

	v0 ^= b;
	v2 ^= 0xff;

	v0 += v1;
	v1 = __builtin_rotateleft64(v1, 13);
	v1 ^= v0;
	v0 = __builtin_rotateleft64(v0, 32);

	v2 += v3;
	v3 = __builtin_rotateleft64(v3, 16);
	v3 ^= v2;
	v2 = __builtin_rotateleft64(v2, 32);

	v0 += v3;
	v3 = __builtin_rotateleft64(v3, 21);
	v3 ^= v0;

	v2 += v1;
	v1 = __builtin_rotateleft64(v1, 17);
	v1 ^= v2;
	v2 = __builtin_rotateleft64(v2, 32);

	b = v0 ^ v1 ^ v2 ^ v3;
	return b;
}

int main() {
	int n, k;
	unsigned long long seed;
	scanf("%d%d%llu", &n, &k, &seed);
	ull st = seed | 1;
