        if (s[i] == '?' || s[i] == t[j]) {

            i++;

            j++;

        } else {

            return false;

        }

    }

    return i == n && j == m;

}

int main() {

    scanf("%d%d", &n, &m);

    scanf("%s%s", s, t);

    puts(match(0, 0) ? "Yes" : "No");

    return 0;

}
